#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# dot8-flag: the two changed blockchain_db commits build (daemon and unit_tests, build/native) with no warnings in the
# changed files; the full unit_tests at the code head; a static monerod of the code head (build/static-head) for the
# box3900x check. Marker FLAGBUILD_DONE in the log.
set -u
. ~/.cargo/env
F=$HOME/work/monerodato; A=$HOME/work/research-artifacts/dot8; L=$HOME/work/dot8_flag_build.log
cd $F
: > $L
[ "$(git rev-parse --abbrev-ref HEAD)" = dot8-flag ] || { echo "not on dot8-flag" >> $L; echo FLAGBUILD_DONE >> $L; exit 1; }
[ -z "$(git status --porcelain --untracked-files=no)" ] || { echo "checkout not clean" >> $L; echo FLAGBUILD_DONE >> $L; exit 1; }
HEADC=$(git rev-parse --short=9 HEAD)
for c in $(git rev-list --reverse b3a2bf8c0..dot8-flag); do
  git checkout -q --detach $c
  if nice -n 5 ninja -C build/native -j12 daemon unit_tests > /tmp/fb_$c.log 2>&1; then r=ok; else r=FAILED; fi
  w=$(grep -E "(liblmdb|blockchain_db|cryptonote_core|lmdb_cachedrop|lmdb_prefetch).*warning" /tmp/fb_$c.log | wc -l)
  echo "$(git log -1 --format='%h %s' $c | cut -c1-90): build $r, warnings in changed files $w" >> $L
done
git checkout -q dot8-flag
build/native/tests/unit_tests/unit_tests > $HOME/work/dot8_flag_ut.log 2>&1; echo "unit_tests exit $?: $(grep -E '^\[  (PASSED|SKIPPED|FAILED)  \]' $HOME/work/dot8_flag_ut.log | tr '\n' ' ')" >> $L
rm -f build/static-head/src/fcmp_pp/fcmp_pp_rust/libfcmp_pp_rust.a
(cd build/static-head && cmake . > /dev/null)
if nice -n 5 ninja -C build/static-head -j10 daemon >> $L.static 2>&1; then
  mkdir -p $A; cp -p build/static-head/bin/monerod $A/monerod-dot8flag-$HEADC
  echo "static $HEADC: $(build/static-head/bin/monerod --version | tail -1); $(sha256sum $A/monerod-dot8flag-$HEADC)" >> $L
  build/static-head/bin/monerod --help 2>/dev/null | grep -A3 "db-cache-drop" >> $L
else echo "static build FAILED" >> $L; fi
echo "back on $(git rev-parse --abbrev-ref HEAD) $(git rev-parse --short=9 HEAD)" >> $L
echo FLAGBUILD_DONE >> $L
